window.kbPageData["views/entry/k-90c98a86d3b2a861"] = {"key":"entry/k-90c98a86d3b2a861","state":{"route":"entry/k-90c98a86d3b2a861"},"node":{"id":"k-90c98a86d3b2a861","mode":"k","title":"营业收入利润率的同比变化","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["营业收入利润率等于利润除以营业收入"],"qs":["江苏 2024 A类 行测#130","江苏 2024 B类 行测#130"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"directorySummary":"营业收入利润率是利润总额与营业收入的比值。统计口径一致且两期营业收入、利润总额均为正时，利润总额的同比增速高于、等于或低于营业收入的同比增速，营业收入利润率就相应同比上升、持平或下降。","review":{"title":"营业收入利润率的同比变化","type":"原理与机制","definition":"营业收入利润率是利润总额与营业收入的比值。统计口径一致且两期营业收入、利润总额均为正时，利润总额的同比增速高于、等于或低于营业收入的同比增速，营业收入利润率就相应同比上升、持平或下降。","explanation":"设利润总额和营业收入的同比增速分别为 a 和 b，现期利润率等于上年同期利润率乘以 (1＋a)/(1＋b)。遇到上年同期利润为零、亏损或盈亏转换时，可在两期营业收入均为正的条件下分别计算利润率，再比较两期数值。","basis":"据关联原题及所列出处编释。","references":[{"source":"profit","location":"附注·营业收入利润率公式；变化条件依公式推导"}],"related":["k-45392942e1591512","k-9ca0533b7efae951","k-14599d5c611e3b87"],"examFocus":{"江苏 2024 A类 行测#130":"从文字材料找出同一监管范围、同一时期的利润与营业收入同比增速，用两者的大小关系判断利润率变动方向。","江苏 2024 B类 行测#130":"从文字材料找出同一监管范围、同一时期的利润与营业收入同比增速，用两者的大小关系判断利润率变动方向。"}},"aspects":[{"title":"比较利润与营业收入的同比增速","uses":[{"unit":"Q1","role":"解题依据","use":"江苏 2024 A类 行测第130题。2023年上半年，江苏省国资委监管企业利润同比增长30.4%，营业收入同比增长4%，据此可推出A项。题干要求选出不能推出的一项，答案为D。图中2022年上半年的营业收入同比增速较前一半年下降，环比增速却上升，D项所称的趋势相同与图中数据不符。","evidence":"2023年上半年，江苏省国资委监管企业营业收入利润率同比有所提高","qids":["江苏 2024 A类 行测#130"]},{"unit":"Q2","role":"解题依据","use":"江苏 2024 B类 行测第130题。A项涉及江苏省国资委监管企业，2023年上半年利润同比增长30.4%，快于营业收入的4%，所以利润率同比提高。该题为选非题，答案同为D。","evidence":"2023年上半年，江苏省国资委监管企业营业收入利润率同比有所提高","qids":["江苏 2024 B类 行测#130"]}]}]},"questions":{"江苏 2024 A类 行测#130":{"paper":"江苏 2024 A类 行测","n":130,"mod":"资料分析","src":["f8fec75f67d6d1ba5759.pdf",26],"asrc":["0126a1c8aceee632ea2b.pdf",40],"card":"52851e610dfeef64f7011bb2","links":[{"id":"k-90c98a86d3b2a861","role":"解题依据","why":"确定利润率的分子和分母后，可用二者的同比增速判断其变化方向。"}]},"江苏 2024 B类 行测#130":{"paper":"江苏 2024 B类 行测","n":130,"mod":"资料分析","src":["0ae7ac475476e5635bd7.pdf",25],"asrc":["8dd171daee6fc74e9718.pdf",43],"card":"e853e29fc67c4eb0bb1b2d10","links":[{"id":"k-90c98a86d3b2a861","role":"解题依据","why":"核验利润率变动时需要确定比值的分子为利润、分母为营业收入。"}]}},"terms":{"k-45392942e1591512":{"id":"k-45392942e1591512","mode":"k","type":"原理与机制","title":"按销量计算总利润","qs":[],"count":2,"basisGroup":"利润与成本","review":true},"k-9ca0533b7efae951":{"id":"k-9ca0533b7efae951","mode":"k","type":"概念与词义","title":"成本利润率","qs":[],"count":2},"k-14599d5c611e3b87":{"id":"k-14599d5c611e3b87","mode":"k","type":"概念与词义","title":"营业收入利润率","qs":[],"count":2}},"references":{"profit":{"name":"国家统计局《2023年全国规模以上工业企业利润下降2.3%》","url":"https://www.stats.gov.cn/xxgk/sjfb/zxfb2020/202401/t20240127_1946916.html"}},"topics":[],"units":{"k-90c98a86d3b2a861":[["江苏 2024 A类 行测#130"],["江苏 2024 B类 行测#130"]]}};
